import{_ as a,o as n,a as p,b as l}from"./app.UgfkfLuP.js";const r=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"同步控制","link":"/api/SIMD-API/tensor_api/sync/sync"},{"text":"mutex","link":"/api/SIMD-API/tensor_api/sync/mutex"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/sync/mutex.md","filePath":"api/SIMD-API/tensor_api/sync/mutex.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1793173587000}'),c={name:"api/SIMD-API/tensor_api/sync/mutex.md"};function e(t,s,o,d,i,_){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>mutex</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR&amp;950DT系列产品：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>tensor_api/tensor.h</code>。</p><p><code>mutex</code>是对象式流水同步句柄。模板参数<code>Pipe</code>在编译期指定流水，构造函数保存运行期硬件锁ID，<code>lock</code>和<code>unlock</code>分别用于获取和释放锁资源。</p><p><code>lock</code>根据<code>mutex_id</code>获取Mutex。若Mutex已被锁定，将阻塞指定流水上后续指令的执行，直到所有流水中具有相同<code>mutex_id</code>的Mutex均已被释放。<code>unlock</code>在指定流水的前序指令执行完成后，根据<code>mutex_id</code>释放对应Mutex。</p><p>mutex用于核内异步流水之间的资源交接，不是CPU线程锁，也不是跨核互斥锁。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">using</span><span class="w"> </span><span class="n">mutex_id</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="kt">uint8_t</span><span class="p">;</span>

<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="n">pipe_t</span><span class="w"> </span><span class="n">Pipe</span><span class="o">&gt;</span>
<span class="k">class</span><span class="w"> </span><span class="nc">mutex</span><span class="w"> </span><span class="p">{</span>
<span class="k">public</span><span class="o">:</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="k">explicit</span><span class="w"> </span><span class="n">mutex</span><span class="p">(</span><span class="n">mutex_id</span><span class="w"> </span><span class="n">id</span><span class="p">)</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">lock</span><span class="p">()</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">unlock</span><span class="p">()</span>

<span class="w">    </span><span class="n">mutex</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">mutex</span><span class="o">&amp;</span><span class="p">)</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">delete</span><span class="p">;</span>
<span class="w">    </span><span class="n">mutex</span><span class="o">&amp;</span><span class="w"> </span><span class="k">operator</span><span class="o">=</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">mutex</span><span class="o">&amp;</span><span class="p">)</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">delete</span><span class="p">;</span>
<span class="w">    </span><span class="n">mutex</span><span class="p">(</span><span class="n">mutex</span><span class="o">&amp;&amp;</span><span class="p">)</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">delete</span><span class="p">;</span>
<span class="w">    </span><span class="n">mutex</span><span class="o">&amp;</span><span class="w"> </span><span class="k">operator</span><span class="o">=</span><span class="p">(</span><span class="n">mutex</span><span class="o">&amp;&amp;</span><span class="p">)</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">delete</span><span class="p">;</span>
<span class="p">};</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th align="left">参数名</th><th align="left">输入/输出</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">Pipe</td><td align="left">-</td><td align="left">编译期模板参数，类型为<code>pipe_t</code>，指定与Mutex关联的流水。</td></tr></tbody></table><p><strong>表2</strong> 接口参数说明</p><table><thead><tr><th align="left">参数名</th><th align="left">输入/输出</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">id</td><td align="left">输入</td><td align="left">构造函数参数，硬件锁ID，类型为<code>mutex_id</code>，即<code>uint8_t</code>。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>构造函数无返回值。<code>lock</code>和<code>unlock</code>无返回值。</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>AIC支持的<code>Pipe</code>取值为<code>PIPE_S</code>、<code>PIPE_M</code>、<code>PIPE_MTE1</code>、<code>PIPE_MTE2</code>、<code>PIPE_FIX</code>；AIV支持的<code>Pipe</code>取值为<code>PIPE_S</code>、<code>PIPE_MTE2</code>、<code>PIPE_MTE3</code>、<code>PIPE_V</code>。</li><li><code>mutex_id</code>由开发者自行管理。同一组同步依赖需要使用相同的<code>mutex_id</code>，不同同步依赖建议使用不同的<code>mutex_id</code>，否则实际同步行为可能与预期不符。</li><li><code>lock</code>与<code>unlock</code>必须严格成对使用，并使用相同的<code>Pipe</code>和<code>mutex_id</code>。对应的<code>unlock</code>必须始终位于<code>lock</code>之后，否则属于未定义行为。</li><li>对于<code>mutex_id</code>相同的<code>lock</code>与<code>unlock</code>组合，无论<code>Pipe</code>是否相同，都不得嵌套使用，否则属于未定义行为。</li><li>当具有相同<code>mutex_id</code>与<code>Pipe</code>的两对<code>lock</code>与<code>unlock</code>连续调用时，第二对<code>lock</code>不能再次阻塞同一流水。因此该写法不能实现同一流水内多条指令之间的顺序控制，单流水内多条指令的顺序控制应使用<a href="sync_pipe.html">sync_pipe</a>。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>以下示例使用mutex保护GM到UB搬入、UB内计算和UB到GM搬出三个流水阶段，保证各阶段按依赖顺序执行。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/tensor.h&quot;</span>

<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">total_length</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">64</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">buffer_lock_id</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>

<span class="n">__global__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">mutex_kernel</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">dst</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">using</span><span class="w"> </span><span class="k">namespace</span><span class="w"> </span><span class="nn">asc</span><span class="o">::</span><span class="nn">te</span><span class="p">;</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="w"> </span><span class="n">buffer</span><span class="p">[</span><span class="n">total_length</span><span class="p">];</span>

<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">layout</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_layout</span><span class="p">(</span><span class="n">make_shape</span><span class="p">(</span><span class="n">total_length</span><span class="p">));</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">src_gm</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_tensor</span><span class="p">(</span><span class="n">make_mem_ptr</span><span class="o">&lt;</span><span class="n">location</span><span class="o">::</span><span class="n">gm</span><span class="o">&gt;</span><span class="p">(</span><span class="n">src</span><span class="p">),</span><span class="w"> </span><span class="n">layout</span><span class="p">);</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">dst_gm</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_tensor</span><span class="p">(</span><span class="n">make_mem_ptr</span><span class="o">&lt;</span><span class="n">location</span><span class="o">::</span><span class="n">gm</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dst</span><span class="p">),</span><span class="w"> </span><span class="n">layout</span><span class="p">);</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">ub_tensor</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_tensor</span><span class="p">(</span><span class="n">make_mem_ptr</span><span class="p">(</span><span class="n">buffer</span><span class="p">),</span><span class="w"> </span><span class="n">layout</span><span class="p">);</span>

<span class="w">    </span><span class="n">mutex</span><span class="o">&lt;</span><span class="n">pipe_t</span><span class="o">::</span><span class="n">PIPE_MTE2</span><span class="o">&gt;</span><span class="w"> </span><span class="n">copy_in_mutex</span><span class="p">(</span><span class="n">buffer_lock_id</span><span class="p">);</span>
<span class="w">    </span><span class="n">copy_in_mutex</span><span class="p">.</span><span class="n">lock</span><span class="p">();</span>
<span class="w">    </span><span class="n">copy</span><span class="p">(</span><span class="n">make_copy</span><span class="p">(</span><span class="n">copy_gm_to_ub</span><span class="p">{}),</span><span class="w"> </span><span class="n">ub_tensor</span><span class="p">,</span><span class="w"> </span><span class="n">src_gm</span><span class="p">);</span>
<span class="w">    </span><span class="n">copy_in_mutex</span><span class="p">.</span><span class="n">unlock</span><span class="p">();</span>

<span class="w">    </span><span class="n">mutex</span><span class="o">&lt;</span><span class="n">pipe_t</span><span class="o">::</span><span class="n">PIPE_MTE3</span><span class="o">&gt;</span><span class="w"> </span><span class="n">copy_out_mutex</span><span class="p">(</span><span class="n">buffer_lock_id</span><span class="p">);</span>
<span class="w">    </span><span class="n">copy_out_mutex</span><span class="p">.</span><span class="n">lock</span><span class="p">();</span>
<span class="w">    </span><span class="n">copy</span><span class="p">(</span><span class="n">make_copy</span><span class="p">(</span><span class="n">copy_ub_to_gm</span><span class="p">{}),</span><span class="w"> </span><span class="n">dst_gm</span><span class="p">,</span><span class="w"> </span><span class="n">ub_tensor</span><span class="p">);</span>
<span class="w">    </span><span class="n">copy_out_mutex</span><span class="p">.</span><span class="n">unlock</span><span class="p">();</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const h=a(c,[["render",e]]);export{r as __pageData,h as default};
